using System;using System.Collections.Generic;using System.IO;using System.Linq;using System.Threading.Tasks;using UnityEngine;using UnityEngine.AI;using RoadGunner;using RoadGunner.Editor;using Object=UnityEngine.Object;
public static class WastelandRouteRecheck {
 static GameSession s;static LevelLayout l;static List<string> lines=new List<string>();static int failures;static Quaternion axis=Quaternion.Euler(0,45,0);static string report="Documentation/RoadGunner/Wasteland-Restore-2026-10-10/RouteRecheck.txt";
 static void Check(string name,bool pass,string detail){if(!pass)failures++;lines.Add((pass?"PASS ":"FAIL ")+name+": "+detail);File.WriteAllLines(report,lines);Debug.Log("WASTELAND "+lines.Last());}
 static async Task Wait(float seconds){float until=Time.realtimeSinceStartup+seconds;while(Time.realtimeSinceStartup<until)await Task.Delay(30);}
 static void Isolate(){s.Restart();s.spawns.enabled=false;s.turret.enabled=false;s.health.DamageEnabled=false;foreach(var r in s.spawns.pool)r.Despawn();foreach(var b in s.spawns.buggyPool)b.Despawn();s.input.testInput=true;s.input.testDirection=Vector2.zero;s.input.testBrake=true;s.vehicle.Body.constraints=RigidbodyConstraints.None;}
 static Vector2 Local(Vector3 world){var p=Quaternion.Inverse(axis)*world;return new Vector2(p.x,p.z);}
 static Vector3 W(float x,float z,float y=.7f)=>axis*new Vector3(x*2.5f,y,z*2.5f);
 static async Task Drive(string name,Vector2 from,Vector2[] route,float yaw=0,float timeout=80){Isolate();s.vehicle.ResetPose(W(from.x,from.y),Quaternion.Euler(0,45+yaw,0));s.follow.Snap();await Wait(.5f);s.input.testBrake=false;int step=0;float end=Time.realtimeSinceStartup+timeout;int minWheels=4;float minUp=1,maxSpeed=0;while(step<route.Length&&Time.realtimeSinceStartup<end){Vector2 delta=route[step]*2.5f-Local(s.vehicle.transform.position);if(delta.magnitude<3){step++;continue;}float throttle=Mathf.Lerp(.36f,.65f,Mathf.InverseLerp(3,12,delta.magnitude));s.input.testDirection=delta.normalized*throttle;minWheels=Math.Min(minWheels,s.vehicle.GroundedWheels);minUp=Mathf.Min(minUp,Vector3.Dot(s.vehicle.transform.up,Vector3.up));maxSpeed=Mathf.Max(maxSpeed,s.vehicle.Body.linearVelocity.magnitude);await Task.Delay(30);}s.input.testDirection=Vector2.zero;s.input.testBrake=true;await Wait(.35f);Check("drive "+name,step==route.Length&&minWheels>=3&&minUp>.9f,"waypoints="+step+"/"+route.Length+", end="+Local(s.vehicle.transform.position)+", minimum grounded="+minWheels+", upright="+minUp.ToString("F3")+", maxSpeed="+maxSpeed.ToString("F2"));}
 static async Task HealRate(string name,float scale){s.health.ResetHealth();s.health.Damage(s.health.tuning.vehicleHealth*.8f,false);Time.timeScale=scale;await Wait(.1f);float hp=s.health.Current,t=Time.time;int frame=Time.frameCount;await Wait(1.5f);float actual=s.health.Current-hp,expected=s.health.tuning.vehicleHealth*.1f*(Time.time-t);Check(name,Mathf.Abs(actual-expected)<1.5f,"healed="+actual.ToString("F3")+", expected="+expected.ToString("F3")+", frames="+(Time.frameCount-frame)+", scaledSeconds="+(Time.time-t).ToString("F3"));Time.timeScale=1;}
 public static async Task<string> Main(){l=Object.FindAnyObjectByType<LevelLayout>();s=l.session;try{
 await Drive("northeast camp",new Vector2(0,36.5f),new[]{new Vector2(14,36.5f),new Vector2(24,40)},90,65);
 await Drive("east road and camp approach",new Vector2(0,22),new[]{new Vector2(15,22),new Vector2(35,23),new Vector2(39,33)},90,95);
 await Drive("service bay entry turn and exit",new Vector2(0,-17),new[]{new Vector2(12,-17),new Vector2(12,-12),new Vector2(12,-7),new Vector2(0,-7)},90,90);
 }finally{s.vehicle.Body.constraints=RigidbodyConstraints.None;s.spawns.enabled=true;s.turret.enabled=true;s.Restart();}return "Failures="+failures+"\n"+string.Join("\n",lines);}
}
